from collections import defaultdict
hits=defaultdict(list)
for line in open('node83_reads_blast.tsv'):
    f=line.rstrip().split('\\t')
    qid=f[0]; gene=f[1].split('|')[5]; ident=float(f[2]); length=int(f[3]); qs=int(f[6]); qe=int(f[7]); ss=int(f[8]); se=int(f[9]); ev=float(f[10])
    hits[qid].append((gene,length,qs,qe,ss,se,ev))
# for each read, find max non-overlapping pair of different genes with q coverage
split=[]; both=[]
for q,hs in hits.items():
    genes=sorted(set(g for g,*_ in hs))
    if len(genes)>=2:
        both.append((q,genes))
    # sort by qstart, take best per gene maybe
    best={}
    for g,l,qs,qe,ss,se,ev in hs:
        if g not in best or l>best[g][0]: best[g]=(l,qs,qe,ss,se,ev)
    arr=sorted(best.values(), key=lambda x:x[1])
    for i in range(len(arr)):
        for j in range(i+1,len(arr)):
            l1,qs1,qe1,_,_,_=arr[i]; l2,qs2,qe2,_,_,_=arr[j]
            if qs2 >= qe1 - 5 and l1>=15 and l2>=15:
                # different genes implied by positions in arr but need mapping gene
                g1=[g for g,v in best.items() if v==arr[i]][0]
                g2=[g for g,v in best.items() if v==arr[j]][0]
                if g1"'!=g2:
                    split.append((q,g1,l1,qs1,qe1,g2,l2,qs2,qe2))
                    break
        if split and split[-1][0]==q: break
print('"'reads with hits to >=2 genes',len(both),'split candidates',len(split))
from collections import Counter
print(Counter((g1,g2) for q,g1,*_,g2,*_ in split).most_common(30))
for rec in split[:50]: print(rec)
